update pages set contenu = '{"sections":[{"type":"heros","h1":"Maintenance machine outil","mecanisme":"Un technicien qui traite la mécanique, les axes et la commande numérique du même bâti, avec des mesures chiffrées plutôt qu''une impression d''opérateur. Broche, vis à billes, glissières, armoire et programme, sur tour, fraiseuse, rectifieuse et centre d''usinage.","cta":"Demander une intervention","telephone":"04 78 33 72 05","phraseDelai":"Nous vous rappelons dans l''heure, du lundi au vendredi de 8h00 à 18h30. Astreinte 24/24 et 7/7."},{"type":"chiffres","chiffres":[{"valeur":"10 %","libelle":"des candidats retenus, après entretien technique ET comportemental"},{"valeur":"+ 100","libelle":"collaborateurs, depuis 4 agences, Lyon (siège), Montréal, Dubaï et Madrid"},{"valeur":"24/24 et 7/7","libelle":"astreinte, pour les sites industriels couverts"}]},{"type":"probleme","punchline":"Une machine outil à l''arrêt, c''est un carnet de commandes qui glisse. La pièce promise pour vendredi partira la semaine suivante.","puces":[{"accroche":"La cote dérive sans aucune alarme.","texte":"Jeu de vis à billes, glissière usée, compensation mal réglée : le produit sort hors tolérance et personne ne le sait avant le contrôle."},{"accroche":"La moitié des heures perdues part en recherche de la cause.","texte":"La machine attend, l''opérateur attend, et le renfort cherche encore où regarder."},{"accroche":"Le même défaut revient tous les deux mois.","texte":"Même symptôme, même poste. Le problème n''est plus le composant, c''est la cause racine que personne n''a traitée."},{"accroche":"Le renfort qui arrive ne sait pas faire.","texte":"Le pire scénario n''est pas la panne. C''est le déplacement payé pour rien, suivi d''un second appel."}]},{"type":"offre","lignes":[{"prestation":"**Un diagnostic qui va à la cause** : mesure des jeux, état de la broche, lecture des défauts affichés par la commande numérique.","benefice":"Vous arrêtez de changer des organes sains pendant que l''atelier attend."},{"prestation":"**Le contrôle géométrique chiffré** : rectitude, perpendicularité, battement, relevés consignés.","benefice":"La dérive se voit avant le rebut, pas après la réclamation client."},{"prestation":"**La mécanique fine reprise dans l''ordre** : broche, roulements, glissières, vis à billes, guidages.","benefice":"Une broche prise tôt, c''est un jeu de roulements. Prise tard, c''est une broche neuve."},{"prestation":"**Les axes et leurs entraînements** : moteurs, courroies, réducteurs, codeurs, défauts de suivi et alarmes variateur.","benefice":"Le cycle cesse de se figer sans que l''opérateur sache pourquoi."},{"prestation":"**La commande numérique traitée en entier** : armoire, variateurs, cartes, paramètres, sauvegarde du programme. Sur CNC, une connexion à distance accélère souvent le diagnostic.","benefice":"Le jour où une carte lâche, on recharge au lieu de tout reprogrammer."},{"prestation":"**Les périphériques suivis** : arrosage, convoyeur à copeaux, changeur d''outil, graissage centralisé, hydraulique et pneumatique.","benefice":"Le changeur bloqué et le filtre saturé sortent de la liste des arrêts subis."},{"prestation":"**Le préventif planifié** : vérification géométrique, graissage, serrages, essais en fonction du temps de marche.","benefice":"Moins d''arrêts subis, un budget lissé au lieu de trois dépannages dans l''année."},{"prestation":"**L''électrique et l''automatisme du même système** : nos automaticiens traitent l''armoire, l''informatique industrielle et les réseaux du site.","benefice":"Une visite au lieu de deux, un seul rapport à classer."}],"prose":[{"texte":"Un parc vieillissant à reprendre en main se traite par le [contrat de maintenance Zéro arrêt](/offres/zero-arret/), qui couvre le programme de visites préventives et la priorité d''intervention. Une machine bloquée maintenant relève du [dépannage industriel en urgence](/offres/depannage-industriel/). Cette expertise prolonge notre [maintenance mécanique](/expertises/mecanique/) sur les équipements les plus exigeants de l''atelier."}]},{"type":"deroule","etapes":[{"titre":"Vous décrivez la situation","texte":"machine, symptôme, code affiché, contexte. Cinq minutes de description font gagner une heure de recherche."},{"titre":"Un technicien vous rappelle dans l''heure.","texte":"Vous savez rapidement si nous avons le profil, et lequel."},{"titre":"Nous cherchons la cause avant de démonter","texte":"mesure des jeux, relevés géométriques, alarmes de la commande numérique, état des périphériques."},{"titre":"Le technicien intervient en autonomie","texte":"consignation, dépose, réparation, remontage, réglage d''axe."},{"titre":"Les essais se font avec votre équipe de production","texte":", jusqu''au retour de la cote et de la cadence."},{"titre":"Vous récupérez un document utile","texte":"cause, travaux réalisés, composants remplacés, relevés, conseil d''entretien pour le prochain passage."}]},{"type":"garanties","puces":[{"accroche":"Le rappel dans l''heure, du lundi au vendredi de 8h00 à 18h30.","texte":"L''astreinte 24/24 et 7/7 couvre la nuit et le week-end sur les sites concernés."},{"accroche":"Vos programmes, vos gammes et vos données restent chez vous.","texte":"Nous n''avons aucun droit de regard au-delà de la mission, quelle que soit sa durée."},{"accroche":"Aucune vente de machine ni de composant.","texte":"Nous ne défendons aucune marque : la solution proposée n''est pas dictée par une vente de matériel, et une remise à niveau bien menée passe souvent avant le rachat."}]},{"type":"cta","question":"Besoin d''un technicien capable de trouver pourquoi la cote dérive ?","bouton":"Demander une intervention","rappel":"Ou appelez le 04 78 33 72 05, du lundi au vendredi de 8h00 à 18h30. Rappel dans l''heure."},{"type":"preuves","preuves":[{"titre":"Maintenance d''un parc usinage, pièces mécaniques de précision","texte":"un technicien intégré à temps plein sur centres d''usinage à grande vitesse, presses et commandes numériques, parc multimarques, 2025","lienLibelle":"Étude de cas VOIT : site du Grand Est","lienHref":"/preuves/voit-grand-est/"},{"titre":"Maintenance préventive et curative d''une fonderie et de son usinage, automobile","texte":"six techniciens affectés au site, 7 jours sur 7, depuis octobre 2023","lienLibelle":"Étude de cas STELLANTIS : fonderie de Sept-Fons","lienHref":"/preuves/stellantis-fonderie-sept-fons/"},{"titre":"Diagnostic et remise en état d''un parc machines défaillant, fabrication de joints","texte":"options chiffrées présentées au client, remise en état plutôt que rachat, depuis février 2024","lienLibelle":"Étude de cas JOINT LYONNAIS : défaillances machines","lienHref":"/preuves/joint-lyonnais/"},{"titre":"Maintien d''un parc machines, équipementier automobile","texte":"un technicien de maintenance dédié et intégré aux équipes du site, 2025","lienLibelle":"Étude de cas AUTOLIV : maintien d''un site","lienHref":"/preuves/autoliv/"},{"titre":"Montée en cadence de plusieurs usines en France, automobile","texte":"trois à cinq techniciens déployés sur lignes de production, ateliers de fabrication et préventif, depuis septembre 2024","lienLibelle":"Étude de cas VALEO : plusieurs usines","lienHref":"/preuves/valeo-usines/"}]},{"type":"objections","questions":[{"question":"Combien coûte une intervention sur machine outil ?","reponse":"Le montant dépend de la panne, de l''accessibilité de l''organe et du niveau d''urgence. Le chiffrage se fait sur devis, déplacement annoncé à l''avance, jamais découvert sur la facture. Quelques minutes au téléphone suffisent à cadrer le besoin."},{"question":"Faut-il signer un contrat pour nous faire intervenir ?","reponse":"Non. Une machine bloquée se traite en intervention ponctuelle. Le contrat Zéro arrêt s''adresse aux sites qui veulent le préventif planifié et la priorité d''intervention. Équipements couverts, fréquence des visites et montant sont définis après diagnostic."},{"question":"Nous avons déjà un prestataire. Comment on bascule ?","reponse":"Nous commençons par un état des lieux du parc, sans jugement sur l''existant : inventaire des machines, points critiques, récupération des historiques disponibles."},{"question":"Qui répond de la sécurité pendant l''intervention ?","reponse":"Vos règles priment sur les nôtres. Plan de prévention signé avant l''arrivée sur site, accueil au poste, permis de feu, consignation, protections individuelles. Notre démarche MASE et notre évaluation EcoVadis sont transmises avec chaque plan de prévention."},{"question":"Qui intervient, et avec quelles habilitations ?","reponse":"Des techniciens retenus à 10 %, après entretien technique et comportemental mené par un homme du métier : lecture de plan, métrologie, réglage d''axe. Habilitations à jour : électrique, consignation, hauteur, espace confiné."},{"question":"Intervenez-vous en urgence, et couvrez-vous notre région ?","reponse":"Oui aux deux, en journée comme en astreinte 24/24 et 7/7. Nos hubs de techniciens couvrent Paris, Lille, Marseille, Toulouse, Lyon, Metz, Strasbourg, Bordeaux, Dijon et Nantes, et nos équipes se déplacent au-delà. Appelez le 04 78 33 72 05."}]},{"type":"ctaFinal","question":"Besoin que vos arrêts machine cessent de revenir tous les deux mois ?","bouton":"Demander une intervention","rappel":"Ou appelez le 04 78 33 72 05, du lundi au vendredi de 8h00 à 18h30. Rappel dans l''heure."}]}'::jsonb where path = '/expertises/mecanique/machine-outil/';
